-- fix_tenant_memberships_role_check.sql
--
-- The original constraint omitted 'super_admin', blocking the dev super-admin
-- bootstrap and the seed_demo_projects.sql script.  This migration widens the
-- allowed role set to match actual app logic and RLS policies.
--
-- Safe to run multiple times (DROP IF EXISTS + ADD).
--
-- Apply via Supabase SQL Editor or:
--   psql "$DATABASE_URL" -f supabase/sql/fix_tenant_memberships_role_check.sql

alter table public.tenant_memberships
  drop constraint if exists tenant_memberships_role_check;

alter table public.tenant_memberships
  add constraint tenant_memberships_role_check
  check (role = any (array['owner', 'admin', 'member', 'viewer', 'super_admin']));
